"""The centrality-and-link-analysis topic. Everything is generated by the kit: no downloads."""
import json

import networkx as nx
import numpy as np
import pandas as pd
import pytest

import ai_learning_kit as kit
from ai_learning_kit.core import registry


@pytest.fixture(autouse=True)
def _isolated(tmp_path, monkeypatch):
    from ai_learning_kit.core import workfolder
    monkeypatch.setattr(workfolder, "START_DIR", tmp_path)
    monkeypatch.chdir(tmp_path)
    kit._state.update(topic=None, problem=None, book=None, folder=None, tools=None)


def _tools():
    from ai_learning_kit.topics.centrality_and_link_analysis import tools
    return tools


def test_topic_contract():
    mod = registry.topic("centrality-and-link-analysis")
    assert mod.PROBLEM is None and mod.TASKS == {} and mod.DATASETS == () and mod.EXTRAS == "graphs"
    ctx = registry.tutor_context("centrality-and-link-analysis")
    json.dumps(ctx)
    assert "pagerank_power" in ctx["tools"]["functions"] and "three stages" in ctx["scope"] and mod.LEVEL == "intermediate"


def test_trio_two_steps():
    T = _tools()
    P, dang = T.transition_matrix(T.trio())
    assert dang == [] and np.allclose(P.sum(axis=1), 1)
    f = T.flow({"Amy": 1}, P, steps=2)
    assert f.loc[1, "Ben"] == 0.5 and f.loc[1, "Clara"] == 0.5
    assert f.loc[2, "Amy"] == 0.5 and f.loc[2, "Ben"] == 0.5 and f.loc[2, "Clara"] == 0
    assert (f.total == 1).all()


def test_toy_design():
    T = _tools()
    G = T.mention_toy()
    U = G.to_undirected()
    deg = dict(U.degree())
    btw = nx.betweenness_centrality(G)
    assert max(deg, key=deg.get) == "Ben" and max(btw, key=btw.get) == "Gianni"   # most links is not the bridge
    assert G.out_degree("Hana") == 0 and G.in_degree("Hana") == 4                  # the dangling node
    assert G["Amy"]["Ben"]["mentions"] == 5                                          # repeated mentions
    assert not nx.has_path(U, "Lea", "Ben")                                          # a separate pair
    assert T.betweenness_by_hand(G, "Gianni").share.sum() == pytest.approx(25.5)
    assert T.betweenness_by_hand(U, "Hana").share.sum() == pytest.approx(11.0)


def test_closeness_disconnected():
    T = _tools()
    c = T.closeness_table(T.mention_toy().to_undirected())
    assert c.loc["Lea", "raw"] == 1.0 and c.loc["Lea", "scaled"] == pytest.approx(1 / 12, abs=1e-4)
    assert c.harmonic.idxmax() == "Gianni"


def test_pagerank_power_matches_networkx():
    T = _tools()
    G = T.mention_toy()
    s, h = T.pagerank_power(G)
    ref = pd.Series(nx.pagerank(G, weight="mentions", tol=1e-12, max_iter=10000))
    assert np.allclose(s.reindex(ref.index), ref, atol=1e-8)
    assert h.total.round(10).eq(1).all()
    _, leak = T.pagerank_power(G, dangling="leak", steps=10)
    assert leak.total.iloc[-1] < 0.5
    s1, _ = T.pagerank_power(G, alpha=1.0, steps=5000)
    assert s1["Lea"] + s1["Mark"] > 0.99                                              # a rank sink without teleportation


def test_hits_and_comparison():
    T = _tools()
    G = T.mention_toy()
    h = T.hits_table(G)
    assert h.authority.idxmax() == "Ben" and abs(h.hub.sum() - 1) < 1e-3
    c = T.compare_rankings({"a": 3, "b": 2, "c": 1}, {"a": 1, "b": 2, "c": 3}, k=1)
    assert c["spearman"] == -1 and c["top1_overlap"] == 0
    H = T.perturb(G, add=("Hana", "Ben", 1))
    assert H.out_degree("Hana") == 1 and G.out_degree("Hana") == 0


def test_forum_matches_reference():
    T = _tools()
    ref = T.reference()["forum"]
    A = T.attention_graph()
    assert A.number_of_nodes() == ref["users"] == 300 and A.number_of_edges() == ref["edges"]
    R = T.reference_ranking()
    assert R.in_degree.idxmax() == ref["top"]["in_degree"][0][0] == "studyhub_announcements"
    assert R.betweenness.idxmax() == ref["top"]["betweenness"][0][0]


def test_checks_pass_on_reference(capsys):
    T = _tools()
    R = T.reference_ranking()
    T.check("P1", R, definition="u -> v: u replied to v; weight replies")
    s, _ = T.pagerank_power(T.attention_graph(), weight="replies")
    T.check("P2", s)
    rows = []
    for a, b in [("in_degree", "pagerank"), ("pagerank", "betweenness")]:
        c = T.compare_rankings(R[a], R[b], k=10)
        rows.append({"first": a, "second": b, "spearman": c["spearman"], "top10_overlap": c["top10_overlap"]})
    T.check("P3", pd.DataFrame(rows))
    A = T.attention_graph()
    B = T.perturb(A, add=("kristina_debono", "francesca_zammit87", 3), weight="replies")
    sh = T.rank_shift(nx.pagerank(A, weight="replies"), nx.pagerank(B, weight="replies"))
    T.check("P4", sh, add=("kristina_debono", "francesca_zammit87", 3))
    out = capsys.readouterr().out
    assert "FAIL" not in out and out.count("PASS") >= 10
    T.check("P2", None)
    assert "Not attempted" in capsys.readouterr().out


def test_quiz():
    T = _tools()
    T.quiz("Q1", "ben")
    T.quiz("q4", 0.5)
